class Solution {
public:
    int strStr(string haystack, string needle) {
        if (needle.empty()) return 0;
        int m = needle.size();
        vector<int> lps(m, 0);
        int prev = 0, i = 1;
        while (i < m) {
            if (needle[i] == needle[prev]) {
                lps[i++] = ++prev;
            } else if (prev > 0) {
                prev = lps[prev - 1];
            } else {
                lps[i++] = 0;
            }
        }

        int j = 0;
        i = 0;
        while (i < haystack.size()) {
            if (haystack[i] == needle[j]) {
                i++;
                j++;
                if (j == m) return i - m;
            } else if (j > 0) {
                j = lps[j - 1];
            } else {
                i++;
            }
        }
        return -1;
    }
};

class Solution {
    public int strStr(String haystack, String needle) {
        if (needle.isEmpty()) return 0;
        int m = needle.length();
        int[] lps = new int[m];
        int prev = 0, i = 1;
        while (i < m) {
            if (needle.charAt(i) == needle.charAt(prev)) {
                lps[i++] = ++prev;
            } else if (prev > 0) {
                prev = lps[prev - 1];
            } else {
                lps[i++] = 0;
            }
        }

        int j = 0;
        i = 0;
        while (i < haystack.length()) {
            if (haystack.charAt(i) == needle.charAt(j)) {
                i++;
                j++;
                if (j == m) return i - m;
            } else if (j > 0) {
                j = lps[j - 1];
            } else {
                i++;
            }
        }
        return -1;
    }
}

