    const m = needle.length;
    const lps = new Int32Array(m);
    let prev = 0, i = 1;
    while (i < m) {
        if (needle[i] === needle[prev]) {
            lps[i++] = ++prev;
        } else if (prev > 0) {
            prev = lps[prev - 1];
        } else {
